"""Text generated by code, not by the model (agent contract §3, recommendations §1–5).

Formatted numbers, reason sentences, group and quadrant names, headline, the recommendation
block and answer_md. Languages with templates: uk, en; any other display language gets
English text and `text_lang: "en"`. Everything here reads plain dicts of result.json, so the
report (plan 07) builds the same text from the file.
"""
from __future__ import annotations

from typing import Any, Dict, List, Optional, Sequence, Tuple

from . import thresholds as T

TEXT_LANGS = ("uk", "en")


def text_lang(display_lang: str) -> str:
    return display_lang if display_lang in TEXT_LANGS else "en"


# --- numbers -----------------------------------------------------------------------------


def _number(x: float, lang: str, digits: int) -> str:
    text = f"{x:.{digits}f}"
    return text.replace(".", ",") if lang == "uk" else text


def signed(x: float, lang: str) -> str:
    """+12 / -3,4 / +8: one decimal below 10 in absolute value unless it is zero; never "-0"."""
    value = round(abs(x), 0 if abs(x) >= 9.95 else 1)
    if value == 0:
        return "0"
    return ("+" if x > 0 else "-") + _number(value, lang, 0 if value == int(value) else 1)


def fmt_growth(x: Optional[float], lang: str) -> Optional[str]:
    if x is None:
        return None
    return f"{signed(x, lang)} %/" + ("рік" if lang == "uk" else "yr")


def fmt_ci(ci: Optional[Sequence[float]], lang: str) -> Optional[str]:
    if ci is None:
        return None
    return f"[{signed(ci[0], lang)}; {signed(ci[1], lang)}]"


def fmt_views(x: Optional[float], lang: str) -> Optional[str]:
    if x is None:
        return None
    text = f"{round(x):,}"
    return text.replace(",", " ") if lang == "uk" else text


def fmt_ppm(x: Optional[float], lang: str) -> Optional[str]:
    if x is None:
        return None
    return fmt_views(x, lang) if x >= 100 else _number(x, lang, 1)


def fmt_pct(x: float, lang: str) -> str:
    return f"{round(x * 100)} %"


