def group_name(group: str, lang: str) -> str:
    return WORDS[lang]["groups"][group]


def quadrant_name(quadrant: str, lang: str, axis: str = "monthly_views") -> str:
    big = WORDS[lang]["size"][axis][0]
    return WORDS[lang]["quadrants"][quadrant].format(big=big)


def size_name(big: Optional[bool], lang: str, axis: str = "monthly_views") -> Optional[str]:
    if big is None:
        return None
    return WORDS[lang]["size"][axis][0 if big else 1]


def criterion_name(name: str, value: Any, lang: str, metric: str = "share") -> str:
    """The growth criterion is on the main metric (recommendations §4)."""
    shown = fmt_views(value, lang) if name == "min_monthly_views" else signed(value, lang).lstrip("+")
    key = f"{name}_views" if name == "min_growth_pct_yr" and metric == "views" else name
    return WORDS[lang]["criteria"][key].format(v=shown)


