def reason_text(code: str, detail: Dict[str, Any], lang: str, labels: Dict[str, str]) -> str:
    words = REASONS[lang]
    basket = WORDS[lang]["basket"].get(str(detail.get("basket")), "")
    if code == "low_volume":
        if detail.get("zero_share", 0) > T.MAX_ZERO_SHARE:
            return words["low_volume_zeros"].format(basket=basket, zeros=fmt_pct(detail["zero_share"], lang))
        return words["low_volume"].format(basket=basket, views=fmt_views(detail["monthly_views"], lang))
    if code == "spike_driven":
        return words[code].format(months=", ".join(detail.get("months", [])))
    if code == "unstable_basket":
        return words[code].format(labels=", ".join(labels.get(q, q) for q in detail.get("qids", [])))
    if code == "concentrated":
        return words[code].format(label=labels.get(detail["qid"], detail["qid"]), share=fmt_pct(detail["share"], lang))
    if code == "short_window":
        return words[code].format(months=detail["months"])
    if code == "short_history":
        return words[code].format(months=detail["history_months"])
    if code == "thin_basket":
        return words[code].format(n=detail["n"])
    if code == "small_effect":
        return words[code].format(flat=signed(T.FLAT_PCT, lang).lstrip("+"))
    if code == "step_like":
        return words[code].format(month=detail["month"])
    if code == "seed_divergence":
        return words[code].format(growth=fmt_growth(detail["growth_pct_yr"], lang))
    if code in ("data_break", "data_revised"):
        return words[code].format(months=", ".join(detail["months"]))
    if code == "trend_reversal":
        return words[code].format(yoy=f"{signed(detail['recent_yoy_pct'], lang)} %")
    if code == "recent_only":
        return words[code].format(months=detail["months"])
    if code == "redirect_heavy":
        return words[code].format(share=fmt_pct(detail["share"], lang))
    if code == "metric_disagreement":
        other = WORDS[lang]["metric"][str(detail.get("other", "views"))]
        return words[code].format(other=other[0].upper() + other[1:], raw=fmt_growth(detail["raw_growth_pct_yr"], lang))
    if code == "project_trend":
        return words[code].format(growth=fmt_growth(detail["project_trend_pct_yr"], lang))
    return words[code]


