def headline(label: str, cells: Sequence[Dict[str, Any]], lang: str) -> str:
    """One sentence per topic: groups in the fixed order, each with its languages (and growth)."""
    parts = []
    for group in ("promising", "emerging", "steady", "weakening", "no_clear_trend", "insufficient_data"):
        members = [c for c in cells if c["group"] == group]
        if not members:
            continue
        with_growth = group in ("promising", "emerging", "weakening")
        items = ", ".join(
            f"{c['lang']} ({c['fmt']['growth']})" if with_growth and c["fmt"].get("growth") else c["lang"] for c in members
        )
        parts.append(SENTENCES[lang]["headline_part"].format(group=group_name(group, lang), items=items))
    return f"{label}: " + "; ".join(parts) + "."


def pair_text(pair: Dict[str, Any], a: Dict[str, Any], b: Dict[str, Any], name_a: str, name_b: str, lang: str,
              metric: str = "share") -> str:
    """A sentence for a pair; `a`/`b` are the two cells (group, fmt). Pairs use the main metric."""
    s = SENTENCES[lang]
    if pair["significant"]:
        key = "pair_significant_views" if metric == "views" else "pair_significant"
        if pair["diff_pct_yr"] < 0:
            return s[key].format(
                a=name_b, b=name_a, diff=fmt_growth(-pair["diff_pct_yr"], lang), ci=fmt_ci([-pair["ci"][1], -pair["ci"][0]], lang))
        return s[key].format(a=name_a, b=name_b, diff=pair["fmt"]["diff"], ci=pair["fmt"]["ci"])
    if a["group"] != b["group"]:
        return s["pair_groups_differ"].format(a=name_a, b=name_b, ga=group_name(a["group"], lang), gb=group_name(b["group"], lang))
    return s["pair_same_group"].format(a=name_a, b=name_b, xa=a["fmt"].get("growth"), xb=b["fmt"].get("growth"))


def _main_reason(cell: Dict[str, Any]) -> Optional[str]:
    for r in cell["reasons"]:
        if r["severity"] in ("blocking", "high", "medium"):
            return r["text"]
    return None


def _criteria_part(cell: Dict[str, Any], criteria: Dict[str, Any], lang: str, metric: str) -> Optional[str]:
    if not cell.get("criteria"):
        return None
    statuses = ", ".join(
        f"{criterion_name(k, criteria[k], lang, metric)} — {WORDS[lang]['status'][v]}" for k, v in cell["criteria"].items())
    return SENTENCES[lang]["criteria_part"].format(statuses=statuses)


def recommendation_texts(
    rec: Dict[str, List[str]], cells: Dict[str, Dict[str, Any]], names: Dict[str, str], criteria: Dict[str, Any],
    lang: str, what: str, metric: str = "share",
) -> Dict[str, Any]:
    """The block of recommendations §5 from the ordered keys: explore / postpone as [{key, text}],
    rest as {keys, text}, and `none` when nothing shows detected growth."""
    s = SENTENCES[lang]
    explore = []
    for key in rec["explore"]:
        cell = cells[key]
        label = quadrant_name(cell["quadrant"], lang) if cell.get("quadrant") else group_name(cell["group"], lang)
        parts = [f"{cell['fmt']['growth']} {cell['fmt']['ci']}"]
        if cell["group"] == "emerging":
            parts.append(s["unconfirmed_because"].format(reason=(_main_reason(cell) or "").rstrip(".").lower()
                                                         if lang == "uk" else (_main_reason(cell) or "").rstrip(".")))
        criteria_part = _criteria_part(cell, criteria, lang, metric)
        if criteria_part:
            parts.append(criteria_part)
        explore.append({"key": key, "text": f"{names[key]} — {label}: " + "; ".join(parts) + "."})
    postpone = []
    for key in rec["postpone"]:
        cell = cells[key]
        not_met = [criterion_name(k, criteria[k], lang, metric) for k, v in cell.get("criteria", {}).items() if v == "not_met"]
        if not_met:
            why = s["not_met"].format(names=", ".join(not_met))
        elif cell["group"] == "weakening":
            why = f"{group_name('weakening', lang)}, {cell['fmt']['growth']} {cell['fmt']['ci']}"
        else:
            why = group_name(cell["group"], lang) + (f" ({_main_reason(cell)})" if _main_reason(cell) else "")
        postpone.append({"key": key, "text": f"{names[key]} — {why}."})
    rest = None
    if rec["rest"]:
        rest = "; ".join(f"{names[k]} — {group_name(cells[k]['group'], lang)}" for k in rec["rest"]) + "."
    none = None if rec["explore"] else s["none_growing"].format(what=s[f"what_{what}"])
    return {"explore": explore, "postpone": postpone, "rest": {"keys": list(rec["rest"]), "text": rest}, "none": none}


# --- answer_md -----------------------------------------------------------------------------


def is_key_cell(cell: Dict[str, Any]) -> bool:
    """Cells detailed even when there are many (agent contract §3); high-severity reasons of
    the other cells are kept too, grouped by code."""
    return cell["status"] == "ok" and (cell["group"] in ("promising", "emerging", "weakening") or cell.get("criteria_met") is True)


def keeps_everything(cell: Dict[str, Any]) -> bool:
    """emerging cells and cells that meet the criteria are never truncated."""
    return cell["group"] == "emerging" or cell.get("criteria_met") is True


def table_header(lang: str, multi_topic: bool, with_criteria: bool) -> List[str]:
    head = list(WORDS[lang]["table"])
    if not multi_topic:
        head.remove(head[1])
    return head if with_criteria else head[:-1]


def table_row(topic: Dict[str, Any], cell: Dict[str, Any], lang: str, multi_topic: bool, with_criteria: bool) -> List[str]:
    """One row of the answer table as cells (answer_md and the PDF table)."""
    w = WORDS[lang]
    if cell["status"] != "ok":
        group = w["failed"]
        values = ["", "", "", "", ""]
    else:
        group = group_name(cell["group"], lang)
        if cell.get("quadrant") in ("big_growing", "growing_niche", "big_stable", "small_stable"):
            group += f" ({quadrant_name(cell['quadrant'], lang)})"
        elif cell.get("size_big") is not None:  # groups without a size split still show the size
            group += f" ({size_name(cell['size_big'], lang)})"
        f = cell["fmt"]
        values = [f.get("growth") or "", f.get("ci") or "", f.get("level_ppm") or "", f.get("monthly_views") or "",
                  w["confidence"][cell["confidence"]]]
    cols = [cell["lang"], *([topic["label"]] if multi_topic else []), group, *values]
    if with_criteria:
        cols.append(", ".join(w["status"][v] for v in cell.get("criteria", {}).values()))
    return cols


def _table(rows: List[Tuple[Dict[str, Any], Dict[str, Any]]], lang: str, multi_topic: bool, with_criteria: bool) -> List[str]:
    head = table_header(lang, multi_topic, with_criteria)
    lines = ["| " + " | ".join(head) + " |", "|" + "---|" * len(head)]
    lines += ["| " + " | ".join(table_row(t, c, lang, multi_topic, with_criteria)) + " |" for t, c in rows]
    return lines


def _more(n: int, lang: str) -> str:
    return SENTENCES[lang]["more"].format(n=n)


def _limited(items: List[str], limit: Optional[int], lang: str) -> List[str]:
    if limit is None or len(items) <= limit:
        return items
    return items[:limit] + [_more(len(items) - limit, lang)]


def _recommendation_lines(texts: Dict[str, Any], lang: str) -> List[str]:
    s = SENTENCES[lang]
    lines = [s["explore"]]
    lines += [f"- {x['text']}" for x in texts["explore"]] or [f"- {texts['none']}"]
    if texts["postpone"]:
        lines += [s["postpone"], *[f"- {x['text']}" for x in texts["postpone"]]]
    if texts["rest"]["text"]:
        lines += [f"{s['rest']} {texts['rest']['text']}"]
    return lines


def answer_sections(result: Dict[str, Any], *, full: bool) -> List[Tuple[str, List[str]]]:
    """Named Markdown sections of the answer, in order: headlines, summary, table, pairs, reasons,
    recommendations, assumptions, next. `full=False` applies the stdout truncation rules; empty
    sections are left out. The report (render.py) lays out the same sections on a page."""
    lang = result["text_lang"]
    s = SENTENCES[lang]
    topics = result["topics"]
    multi_topic = len(topics) > 1
    criteria = result.get("criteria") or {}
    metric = result.get("metric", "share")
    all_cells = [(t, c) for t in topics for c in t["cells"]]
    many = not full and len(all_cells) > T.MAX_DETAILED_CELLS
    shown = [(t, c) for t, c in all_cells if not many or is_key_cell(c)]
    key_cells = {(t["id"], c["lang"]) for t, c in shown}

    sections: List[Tuple[str, List[str]]] = [("headlines", [f"**{t['headline']}**" for t in topics])]
    if many:
        counts: Dict[str, int] = {}
        for _, c in all_cells:
            counts[c["group"]] = counts.get(c["group"], 0) + 1
        items = "; ".join(f"{group_name(g, lang)} — {n}" for g, n in counts.items())
        sections.append(("summary", [s["summary"].format(items=items)]))
    table = _table(shown, lang, multi_topic, bool(criteria))
    if len(shown) < len(all_cells):
        table.append(_more(len(all_cells) - len(shown), lang))
    sections.append(("table", table))

    def pair_kept(p: Dict[str, Any], a: Tuple[str, str], b: Tuple[str, str]) -> bool:
        return full or (p["shown"] and (not many or (a in key_cells and b in key_cells)))

    sentences = []
    for t in topics:
        if t.get("pairs_skipped") == "no_common_basket" and len(t["cells"]) > 1:
            sentences.append(s["no_pairs"])
        sentences += [p["text"] for p in t["pairs"] if pair_kept(p, (t["id"], p["a"]), (t["id"], p["b"]))]
    for entry in result.get("by_lang", []):
        sentences += [p["text"] for p in entry["pairs"] if pair_kept(p, (p["a"], entry["lang"]), (p["b"], entry["lang"]))]
    if sentences:
        sections.append(("pairs", sentences))

    reason_lines = []
    for t, c in shown:
        if not c["reasons"]:
            continue
        limit = None if full or keeps_everything(c) else T.MAX_REASONS_SHOWN
        texts = _limited([r["text"] for r in c["reasons"]], limit, lang)
        where = f"{c['lang']}, {t['label']}" if multi_topic else c["lang"]
        reason_lines.append(f"- **{where}:** " + " ".join(texts))
    if many:  # high-severity reasons of the cells not detailed above: grouped by code, never dropped
        grouped: Dict[str, List[str]] = {}
        for t, c in all_cells:
            if (t["id"], c["lang"]) in key_cells:
                continue
            for r in c["reasons"]:
                if r["severity"] == "high" or r["code"] == "low_volume":
                    where = f"{c['lang']} · {t['label']}" if multi_topic else c["lang"]
                    grouped.setdefault(r["code"], []).append(where)
        for code, where in grouped.items():
            title = REASON_TITLES[lang].get(code, code)
            reason_lines.append("- " + s["grouped_reason"].format(title=title, code=code, cells=", ".join(where)))
    if reason_lines:
        sections.append(("reasons", [s["h_reasons"], *reason_lines]))

    rec_blocks = [(t["label"], t["recommendations"]) for t in topics if t.get("recommendations")]
    rec_blocks += [(s["in_lang"].format(lang=e["lang"]), e["recommendations"]) for e in result.get("by_lang", [])
                   if e.get("recommendations")]
    if rec_blocks:
        lines = [s["h_recommend"]]
        if many:  # only what to explore next; the full blocks are in answer_md_full
            explore = [f"- *{title}:* " + " ".join(x["text"] for x in texts["explore"]) for title, texts in rec_blocks if texts["explore"]]
            lines += [s["explore"], *explore] if explore else [s["explore"], f"- {rec_blocks[0][1]['none']}"]
            hidden = sum(len(texts["postpone"]) + len(texts["rest"]["keys"]) for _, texts in rec_blocks)
            if hidden:
                lines.append(_more(hidden, lang))
        else:
            for title, texts in rec_blocks:
                if len(rec_blocks) > 1:
                    lines.append(f"*{title}*")
                lines += _recommendation_lines(texts, lang)
        lines.append(s["order_rule"])
        sections.append(("recommendations", lines))

    lines = [s["h_assumptions"]]
    for t in topics:
        labels = _limited([i["label"] for i in t["items"]], None if full else T.MAX_EXCLUDED_SHOWN, lang)
        lines.append("- " + s["basket_line"].format(topic=t["label"], n=len(t["common"]), labels=", ".join(labels)))
        if not t["common"]:
            lines.append("- " + s["basket_local"].format(topic=t["label"]))
        if t["excluded"]:
            items = [f"{e['label']} ({e['lang']}: {e['code']}{':' + e['detail'] if e.get('detail') else ''})" for e in t["excluded"]]
            items = _limited(items, None if full else T.MAX_EXCLUDED_SHOWN, lang)
            lines.append("- " + s["excluded"].format(items=", ".join(items)))
    lines.append("- " + s["basket_note"])
    period = result["period"]
    lines.append("- " + s["metric_line_views" if metric == "views" else "metric_line"].format(start=period["start"], end=period["end"]))
    if criteria:
        lines.append("- " + s["criteria_line"].format(
            items=", ".join(criterion_name(k, v, lang, metric) for k, v in criteria.items())))
        threshold = criteria.get("min_growth_pct_yr")
        for t, c in all_cells:
            raw = c.get("raw_growth_pct_yr")
            if (threshold is not None and c.get("criteria", {}).get("min_growth_pct_yr") == "met"
                    and raw is not None and raw < threshold):
                key = f"{c['lang']} ({t['label']})" if multi_topic else c["lang"]
                lines.append("- " + s["raw_below_views" if metric == "views" else "raw_below"].format(key=key, raw=fmt_growth(raw, lang), threshold=threshold))
    if any(c.get("direction") == "declining" or c["group"] == "weakening" for _, c in all_cells):
        lines.append("- " + s["weakening_caveat"])
    lines += ["- " + s["market"], "- " + s["no_forecast"]]
    sections.append(("assumptions", lines))
    sections.append(("next", [s["h_next"], "- " + s["next"]]))
    return sections


def answer_md(result: Dict[str, Any], *, full: bool) -> str:
    """The answer skeleton (agent contract §3); `full=False` applies the stdout truncation rules."""
    return "\n\n".join("\n".join(lines) for _, lines in answer_sections(result, full=full))
